const e=[{id:"poi-jezero-delta",name:"Jezero Crater Western Fan Delta",category:"ancient_delta",description:"Prominent river delta deposit formed by ancient inflow from Neretva Vallis into a palaeolake approximately 3.7 billion years ago.",scientificRelevance:"High priority astrobiological target. Contains fine-grained smectite clays and carbonate minerals optimal for preserving biosignatures of ancient microbial life.",coordinates:{latitude:18.4447,longitude:77.4508,elevationMeters:-2530},elevationMeters:-2530,mission:"Mars 2020 / Perseverance Rover",instrument:"SuperCam, PIXL, SHERLOC, Mastcam-Z",sourceUrl:"https://mars.nasa.gov/mars2020/mission/science/landing-site/",datasetId:"PDS4_M2020_SUPERCAM_L2",observationDate:"2021-Present",limitations:["Delta front features steep erosion scarps with talus slopes up to 24 degrees.","Surface contains loose pebbles and fractured mudstones causing rover wheel slippage."],keyMineralsOrFeatures:["Iron-magnesium smectite clays","Carbonates","Cross-bedded sandstone units"]},{id:"poi-jezero-kodiak",name:"Kodiak Butte Delta Remnant",category:"ancient_delta",description:"Isolated erosional butte south of the main delta exhibiting classical Gilbert-type bottomset, foreset, and topset sediment architectures.",scientificRelevance:"Confirms that Jezero hosted a sustained, closed-basin body of standing water that fluctuated over geological epochs.",coordinates:{latitude:18.397,longitude:77.412,elevationMeters:-2480},elevationMeters:-2480,mission:"Mars 2020 / Perseverance Rover",instrument:"Mastcam-Z Long-range Reconnaissance",sourceUrl:"https://www.nasa.gov/image-feature/jpl/perseverance-views-kodiak-butte/",observationDate:"2021-04-18",limitations:["Steep cliffs around butte perimeter render direct astronaut ascent impossible without mountaineering tethers.","Observations conducted primarily via remote optical telephoto sensors."],keyMineralsOrFeatures:["Topset conglomerate strata","Steep dipping foreset beds"]},{id:"poi-gale-mount-sharp",name:"Mount Sharp (Aeolis Mons) Basal Stratigraphy",category:"crater",description:"Central mound in Gale Crater rising 5.5 km from the crater floor, displaying layered sedimentary strata that record billions of years of Martian climate transition.",scientificRelevance:"Traces the transition from wet, potentially habitable conditions (clay-bearing units) to arid conditions (sulfate-bearing units).",coordinates:{latitude:-5.08,longitude:137.85,elevationMeters:-4450},elevationMeters:-4450,mission:"Mars Science Laboratory (MSL) / Curiosity Rover",instrument:"SAM, CheMin, ChemCam, APXS",sourceUrl:"https://mars.nasa.gov/msl/mission/science/summary/",datasetId:"PDS_MSL_CHEMIN_V1",observationDate:"2012-Present",limitations:["Basal slopes feature knife-edge clay-capped ridges and active eolian sand dunes (Bagnold Dunes) posing wheel trap hazards.","Significant elevation gain requiring high metabolic energy expendable by suited crew."],keyMineralsOrFeatures:["Nontronite","Jarosite","Calcium sulfate veins","Hematite"]},{id:"poi-olympus-mons-caldera",name:"Olympus Mons Central Caldera Rim",category:"volcano",description:"Summit caldera complex of the Solar System’s largest shield volcano, encompassing six nested collapsed calderas reaching an altitude of 21.9 km above Mars datum.",scientificRelevance:"Provides critical insights into the thermal history, planetary interior dynamics, and prolonged basaltic plume volcanism of Mars.",coordinates:{latitude:18.65,longitude:-133.8,elevationMeters:21287},elevationMeters:21287,mission:"Mars Global Surveyor / Mars Express / MRO",instrument:"HRSC (High Resolution Stereo Camera), MOLA",sourceUrl:"https://www.esa.int/Science_Exploration/Space_Science/Mars_Express/Olympus_Mons_the_volcano_of_extremes",observationDate:"2004-Present",limitations:["Atmospheric pressure is less than 0.7 millibars (near vacuum), requiring specialized high-altitude life support.","Outer basal scarp reaches 6 to 8 km sheer drops."],keyMineralsOrFeatures:["Tholeiitic basalt","Nested collapse pit craters","Extensive lava tubes"]},{id:"poi-valles-marineris-melas",name:"Melas Chasma Layered Internal Deposits",category:"chasma",description:"Widest and deepest canyon section of the Valles Marineris canyon system, dropping over 9 km below the surrounding volcanic plateaus.",scientificRelevance:"Exposes deep crustal bedrock sections and extensive Light-Toned Deposits (LTDs) containing hydrated sulfates formed in ancient subaqueous environments.",coordinates:{latitude:-9.8,longitude:-76.4,elevationMeters:-3900},elevationMeters:-3900,mission:"Mars Reconnaissance Orbiter / CRISM",instrument:"CRISM, HiRISE",sourceUrl:"https://crism.jhuapl.edu/gallery/featuredImage.php?image_id=262",observationDate:"2008-03-12",limitations:["Severe microclimatic wind turbulence and periodic local canyon dust storms.","Enormous landslide debris deposits impede surface traversal."],keyMineralsOrFeatures:["Kieserite","Polyhydrated sulfates","Layered silicates"]},{id:"poi-meridiani-victoria",name:"Victoria Crater Sulfate Exposures",category:"crater",description:"800-meter-wide impact crater in Meridiani Planum explored by the Opportunity rover for nearly two Earth years.",scientificRelevance:'Exposes vertical stratigraphy of sulfate-rich sandstones and hematite spherules ("blueberries") recording past groundwater percolation.',coordinates:{latitude:-2.05,longitude:-5.5,elevationMeters:-1390},elevationMeters:-1390,mission:"Mars Exploration Rover (MER-B) / Opportunity",instrument:"Pancam, Microscopic Imager, APXS, Mössbauer",sourceUrl:"https://mars.nasa.gov/mer/mission/science/results/",observationDate:"2006-2008",limitations:["Crater rim consists of alternating alcoves and steep promontories with loose sandy chutes.","Opportunity experienced serious wheel slippage while ascending Duck Bay."],keyMineralsOrFeatures:["Hematite spherules","Cross-stratified eolian sandstones","Gypsum veins"]},{id:"poi-arcadia-ice",name:"Arcadia Planitia Subsurface Glacial Ice Sheet",category:"ice_deposit",description:"Extensive low-latitude subsurface water ice sheets buried beneath 1 to 2.5 meters of protective dry Martian regolith.",scientificRelevance:"Highest priority candidate for In-Situ Resource Utilization (ISRU) water extraction and future human Mars base life-support sustainment.",coordinates:{latitude:39.3,longitude:-170.3,elevationMeters:-3950},elevationMeters:-3950,mission:"Mars Reconnaissance Orbiter / SHARAD Radar",instrument:"Shallow Radar (SHARAD), Mars Climate Sounder",sourceUrl:"https://www.nasa.gov/feature/jpl/nasas-treasure-map-for-water-ice-on-mars",observationDate:"2019-12-10",limitations:["Subsurface ice requires drilling or excavation; radar dielectric reflections indicate varied overburden thickness.","Winter surface temperatures fall below -110°C with seasonal carbon dioxide frost."],keyMineralsOrFeatures:["High-purity water ice (>90%)","Periglacial patterned ground"]}];export{e as S};
